// Jonker-Volgenant assignment, adapted from classic lap.cpp (public domain style)
// Minimizes sum cost[i*n + col[i]]
#include <cstdint>
#include <cstring>
#include <vector>
#include <limits>
#include <algorithm>

extern "C" {

void lapjv(int n, const double* cost, int* x, int* y) {
    const double INF = 1e18;
    std::vector<double> u(n+1), v(n+1), minv(n+1);
    std::vector<int> p(n+1), way(n+1);
    std::vector<char> used(n+1);
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        std::fill(minv.begin(), minv.end(), INF);
        std::fill(used.begin(), used.end(), 0);
        do {
            used[j0] = 1;
            int i0 = p[j0], j1 = 0;
            double delta = INF;
            const double* crow = cost + (size_t)(i0-1)*n;
            double ui = u[i0];
            for (int j = 1; j <= n; ++j) if (!used[j]) {
                double cur = crow[j-1] - ui - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    for (int j = 1; j <= n; ++j) {
        x[p[j]-1] = j-1;
        y[j-1] = p[j]-1;
    }
}

}
