// Dense LAPJV with column reduction + augmenting row reduction + Dijkstra augmentation.
// Algorithm: Jonker & Volgenant, "A shortest augmenting path algorithm for dense
// and sparse linear assignment problems", Computing 1987.
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cmath>

extern "C" void lapjv2(int n, const double* cost, int* rowsol_out) {
    const double INF = 1e100;
    const int n1 = n + 1;

    std::vector<double> u(n1, 0.0), v(n1, 0.0), d(n1);
    std::vector<int> rowsol(n1, 0);   // row -> col (1-based), 0 = free
    std::vector<int> colsol(n1, 0);   // col -> row
    std::vector<int> pred(n1, 0);
    std::vector<int> free_rows;
    free_rows.reserve(n);
    std::vector<char> collist_scanned(n1);

    auto C = [&](int i, int j) -> double {
        return cost[(size_t)(i - 1) * n + (j - 1)];
    };

    // ---------- COLUMN REDUCTION ----------
    // For each column (from n down to 1), assign it to the row with smallest cost
    // if that row is still free. v[j] = min cost in the column.
    std::vector<char> row_free(n1, 1);
    for (int j = n; j >= 1; --j) {
        double mn = INF;
        int imin = 1;
        for (int i = 1; i <= n; ++i) {
            double h = C(i, j);
            if (h < mn) { mn = h; imin = i; }
        }
        v[j] = mn;
        if (row_free[imin]) {
            rowsol[imin] = j;
            colsol[j] = imin;
            row_free[imin] = 0;
        }
    }
    for (int i = 1; i <= n; ++i) if (row_free[i]) free_rows.push_back(i);

    // dual u for assigned rows
    for (int i = 1; i <= n; ++i) if (rowsol[i]) {
        u[i] = C(i, rowsol[i]) - v[rowsol[i]];
    }

    // ---------- REDUCTION TRANSFER ----------
    {
        std::vector<int> still;
        still.reserve(free_rows.size());
        for (int i : free_rows) {
            double mn = INF;
            int j1 = 1;
            for (int j = 1; j <= n; ++j) {
                double h = C(i, j) - v[j];
                if (h < mn) { mn = h; j1 = j; }
            }
            u[i] = mn;
            int i0 = colsol[j1];
            if (i0 == 0) {
                // free column, assign
                rowsol[i] = j1; colsol[j1] = i; row_free[i] = 0;
                continue;
            }
            // second best reduced cost of the currently assigned row i0
            double mn2 = INF;
            for (int j = 1; j <= n; ++j) if (j != j1) {
                double h = C(i0, j) - v[j] - u[i0];
                if (h < mn2) mn2 = h;
            }
            if (mn2 > 0) { // i0 has a unique minimum at j1; cannot transfer? actually mn2>=0 always if u correct
                // transfer only if i0 has an alternative zero
            }
            if (mn2 == 0.0) {
                // transfer: i takes j1, i0 becomes free (it has another zero)
                // find an alternative column for bookkeeping not needed
                rowsol[i] = j1; colsol[j1] = i; row_free[i] = 0;
                rowsol[i0] = 0; row_free[i0] = 1;
                u[i0] = 0; // will be recomputed
                still.push_back(i0);
            } else {
                still.push_back(i);
            }
        }
        free_rows.swap(still);
    }

    // ---------- AUGMENTING ROW REDUCTION (2 passes) ----------
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> still;
        still.reserve(free_rows.size());
        for (int i : free_rows) {
            double umin = INF, usubmin = INF;
            int jmin = 0;
            for (int j = 1; j <= n; ++j) {
                double h = C(i, j) - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                    } else {
                        usubmin = umin;
                        umin = h;
                        jmin = j;
                    }
                }
            }
            u[i] = umin;
            int i0 = colsol[jmin];
            if (umin < usubmin) {
                v[jmin] -= (usubmin - umin);
            } else if (i0 != 0 && pass == 0) {
                // not unique and column taken: defer
                still.push_back(i);
                continue;
            }
            // assign jmin to i
            if (i0 != 0) {
                rowsol[i0] = 0;
                row_free[i0] = 1;
                still.push_back(i0);
            }
            rowsol[i] = jmin;
            colsol[jmin] = i;
            row_free[i] = 0;
        }
        free_rows.swap(still);
        if (free_rows.empty()) break;
    }

    // ---------- AUGMENTATION (Dijkstra) ----------
    std::vector<int> ready;
    for (int freerow : free_rows) {
        std::fill(collist_scanned.begin(), collist_scanned.end(), 0);
        int endofpath = -1;
        double freerow_dual = 0.0;
        for (int j = 1; j <= n; ++j) {
            d[j] = C(freerow, j) - v[j];
            pred[j] = freerow;
        }
        while (true) {
            // find unscanned column with smallest d
            double mn = INF;
            int jmin = 0;
            for (int j = 1; j <= n; ++j) if (!collist_scanned[j] && d[j] < mn) {
                mn = d[j]; jmin = j;
            }
            collist_scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i == 0) { endofpath = jmin; freerow_dual = mn; break; }
            // scan row i
            double ui_shift = C(i, jmin) - v[jmin] - mn;
            for (int j = 1; j <= n; ++j) if (!collist_scanned[j]) {
                double h = C(i, j) - v[j] - ui_shift;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        // update dual variables of scanned columns
        for (int j = 1; j <= n; ++j) if (collist_scanned[j]) {
            double delta = d[j] - freerow_dual;
            v[j] += delta;
            int i = colsol[j];
            if (i > 0) u[i] -= delta;
        }
        u[freerow] = freerow_dual;

        // augment along path
        int j = endofpath;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nextj = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = nextj;
        }
    }

    for (int i = 1; i <= n; ++i) rowsol_out[i - 1] = rowsol[i] - 1;
}
