import numpy as np, ot, time, ctypes
from reference import Task
lib = ctypes.CDLL("./build/lapjv2.so")
lib.lapjv2.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]

def lap(M):
    n = M.shape[0]
    Mc = np.ascontiguousarray(M, dtype=np.float64)
    x = np.empty(n, dtype=np.int32)
    lib.lapjv2(n, Mc.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), x.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return x

t = Task()
ok = 0
for seed in range(8):
    for n in (20, 50, 100, 200):
        p = t.generate_problem(n=n, random_seed=seed+1)
        a = np.asarray(p["source_weights"], np.float64)
        M = np.ascontiguousarray(p["cost_matrix"], np.float64)
        G = ot.lp.emd(a, a, M, check_marginals=False)
        cols = lap(M)
        if len(set(cols.tolist())) != n or np.any(cols < 0):
            print("INVALID assignment", n, seed, cols[:10]); continue
        Gp = np.zeros_like(M)
        Gp[np.arange(n), cols] = a[0]
        match = np.allclose(Gp, G, atol=1e-7)
        cost_ok = abs(np.sum(Gp*M) - np.sum(G*M)) < 1e-8
        if not match:
            print("DIFF", n, seed, "cost_ok", cost_ok, "maxdiff", np.max(np.abs(Gp-G)))
        else:
            ok += 1
print("matches", ok)
# timing
for n in (200, 400, 600):
    p = t.generate_problem(n=n, random_seed=5)
    a = np.asarray(p["source_weights"], np.float64)
    M = np.ascontiguousarray(p["cost_matrix"], np.float64)
    lap(M)
    st = time.perf_counter(); G = ot.lp.emd(a, a, M, check_marginals=False); t1 = time.perf_counter()-st
    st = time.perf_counter(); cols = lap(M); t2 = time.perf_counter()-st
    Gp = np.zeros_like(M); Gp[np.arange(n), cols] = a[0]
    print(n, "emd", round(t1,4), "lap2", round(t2,4), "match", np.allclose(Gp, G, atol=1e-8), "sp", round(t1/t2,2))
