// Bertsekas epsilon-scaling auction for the dense assignment problem.
// Returns a minimum-cost assignment for costs that are well-scaled.
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdint>

extern "C" void auction(int n, const double* cost, int* rowsol, double eps_final) {
    // We maximize -cost, i.e. benefits b[i][j] = -cost[i][j]
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);      // column -> row
    std::vector<int> assign(n, -1);     // row -> column
    std::vector<int> unassigned;
    unassigned.reserve(n);

    // scale: eps starts large
    double cmax = 0.0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) cmax = std::max(cmax, cost[k]);
    double eps = std::max(cmax / 2.0, eps_final);

    auto run = [&](double eps) {
        std::fill(price.begin(), price.end(), 0.0);
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);
        int guard = 0;
        const int GUARD_MAX = n * 100;
        while (!unassigned.empty() && guard++ < GUARD_MAX) {
            int i = unassigned.back();
            unassigned.pop_back();
            const double* crow = cost + (size_t)i * n;
            // find best and second best value = -cost - price
            double best = -1e300, second = -1e300;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double val = -crow[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            double bid = price[jbest] + (best - second) + eps;
            price[jbest] = bid;
            int prev = owner[jbest];
            owner[jbest] = i;
            assign[i] = jbest;
            if (prev >= 0) {
                assign[prev] = -1;
                unassigned.push_back(prev);
            }
        }
    };

    while (true) {
        run(eps);
        if (eps <= eps_final * 1.0001) break;
        eps = std::max(eps_final, eps * 0.25);
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
}
