// Min-cost assignment on a sparse bipartite graph (each left node has a list of candidate right nodes).
// Successive shortest paths with potentials (Jonker-Volgenant style Dijkstra).
// cand_idx: n*k int32, cand_cost: n*k double. Returns 0 on success, -1 if no perfect matching in the graph.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>

extern "C" int sparse_lap(int n, int k, const int* cand_idx, const double* cand_cost, int* rowsol) {
    const double INF = 1e100;
    // adjacency of columns -> list of (row, local_slot) for reverse? We only scan from rows.
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred_row(n), pred_slot(n);
    std::vector<char> scanned(n);

    // heuristic init: greedy
    std::vector<char> col_taken(n, 0);
    for (int i = 0; i < n; ++i) {
        int best = -1; double bc = INF;
        const double* cc = cand_cost + (size_t)i * k;
        const int* ci = cand_idx + (size_t)i * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            if (!col_taken[j] && cc[s] < bc) { bc = cc[s]; best = s; }
        }
        if (best >= 0) {
            int j = ci[best];
            col_taken[j] = 1;
            col_of_row[i] = j;
            row_of_col[j] = i;
            u[i] = bc;
            v[j] = 0;
        }
    }

    auto reduced = [&](int i, int s) -> double {
        int j = cand_idx[(size_t)i * k + s];
        return cand_cost[(size_t)i * k + s] - u[i] - v[j];
    };

    for (int freerow = 0; freerow < n; ++freerow) {
        if (col_of_row[freerow] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        // init distances from freerow
        {
            const int* ci = cand_idx + (size_t)freerow * k;
            const double* cc = cand_cost + (size_t)freerow * k;
            for (int s = 0; s < k; ++s) {
                int j = ci[s];
                double d = cc[s] - u[freerow] - v[j];
                if (d < dist[j]) { dist[j] = d; pred_row[j] = freerow; pred_slot[j] = s; }
            }
        }
        int endcol = -1;
        double enddist = 0;
        while (true) {
            double mn = INF; int jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < mn) { mn = dist[j]; jmin = j; }
            if (jmin < 0) return -1; // disconnected
            scanned[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { endcol = jmin; enddist = mn; break; }
            // relax from row i
            const int* ci = cand_idx + (size_t)i * k;
            const double* cc = cand_cost + (size_t)i * k;
            // ui consistent: cost(i, jmin) - v[jmin] - mn  == u[i] + (dist slack)
            // reduced cost of edge i->j relative to path: cc - u_i_new - v[j]
            // u_i should satisfy cc_matched - u[i] - v[jmin] = 0 after update, so
            // tentative u shift: 
            double ui = cc[0]; // dummy
            // find slot of jmin
            double cmatch = 0;
            for (int s = 0; s < k; ++s) if (ci[s] == jmin) { cmatch = cc[s]; break; }
            double ui_new = cmatch - v[jmin] - mn;
            for (int s = 0; s < k; ++s) {
                int j = ci[s];
                if (scanned[j]) continue;
                double nd = cc[s] - ui_new - v[j];
                if (nd < dist[j]) { dist[j] = nd; pred_row[j] = i; pred_slot[j] = s; }
            }
            (void)ui;
        }
        // update potentials for scanned columns
        for (int j = 0; j < n; ++j) if (scanned[j]) {
            double delta = dist[j] - enddist;
            v[j] += delta;
            int i = row_of_col[j];
            if (i >= 0) u[i] -= delta;
        }
        u[freerow] += enddist; // freerow had u possibly 0; set so reduced of first edge is 0
        // Actually set u[freerow] from the matched edge after augment. Do augment first.

        // augment
        int j = endcol;
        while (true) {
            int i = pred_row[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            if (i == freerow) break;
            j = prev;
        }
        // fix u[freerow]
        {
            int j = col_of_row[freerow];
            const int* ci = cand_idx + (size_t)freerow * k;
            const double* cc = cand_cost + (size_t)freerow * k;
            for (int s = 0; s < k; ++s) if (ci[s] == j) { u[freerow] = cc[s] - v[j]; break; }
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
