// Successive shortest paths for sparse assignment.
// cand_idx, cand_cost: row-major n*k. Every matched edge must be in the candidate list.
// Returns 0 on success, -1 if the candidate graph has no perfect matching.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int sparse_lap(int n, int k, const int* cand_idx, const double* cand_cost, int* rowsol) {
    const double INF = 1e100;

    std::vector<double> pot(n, 0.0);          // column potentials (pi)
    std::vector<int> col_of_row(n, -1);
    std::vector<int> row_of_col(n, -1);
    std::vector<int> slot_of_match(n, -1);    // for matched row, slot of its column

    std::vector<double> dist(n);
    std::vector<int> parent_row(n);
    std::vector<char> used(n);

    // reverse adjacency: for each column, rows that list it (to speed? not required)
    for (int source = 0; source < n; ++source) {
        if (col_of_row[source] >= 0) continue;

        std::fill(dist.begin(), dist.end(), INF);
        std::fill(used.begin(), used.end(), 0);

        const int* ci = cand_idx + (size_t)source * k;
        const double* cc = cand_cost + (size_t)source * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            double d = cc[s] - pot[j];
            if (d < dist[j]) {
                dist[j] = d;
                parent_row[j] = source;
            }
        }

        int sink = -1;
        double sink_d = 0.0;
        while (true) {
            int jmin = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) if (!used[j] && dist[j] < best) {
                best = dist[j];
                jmin = j;
            }
            if (jmin < 0 || best >= INF / 2) return -1;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; sink_d = best; break; }

            // relax edges out of the matched row i, using reduced costs with updated potential
            // reduced cost of matched edge is 0, so u_i = c(i,jmin) - pot[jmin] - dist[jmin]
            int sm = slot_of_match[i];
            double cmatch = cand_cost[(size_t)i * k + sm];
            double ui = cmatch - pot[jmin] - best;
            const int* ci2 = cand_idx + (size_t)i * k;
            const double* cc2 = cand_cost + (size_t)i * k;
            for (int s = 0; s < k; ++s) {
                int j = ci2[s];
                if (used[j]) continue;
                double nd = cc2[s] - ui - pot[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    parent_row[j] = i;
                }
            }
        }

        // update column potentials for used columns
        for (int j = 0; j < n; ++j) if (used[j]) pot[j] += dist[j] - sink_d;

        // augment
        int j = sink;
        while (true) {
            int i = parent_row[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            // find slot
            const int* ci3 = cand_idx + (size_t)i * k;
            int slot = -1;
            for (int s = 0; s < k; ++s) if (ci3[s] == j) { slot = s; break; }
            slot_of_match[i] = slot;
            if (i == source) break;
            j = prev;
        }
    }

    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
