// Geometric assignment: for each of n sources and n targets in R^2,
// solve min-cost assignment with cost = euclidean distance, restricted to
// each source's k nearest targets, via successive shortest paths + binary heap.
//
// If the k-NN graph has no perfect matching, returns -1.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <queue>

struct Node {
    double d;
    int j;
    bool operator<(const Node& o) const { return d > o.d; } // min-heap
};

extern "C" int geo_lap(int n, int k,
                       const double* src, const double* tgt,
                       int* rowsol, double* col_cost_out) {
    // Build k-NN lists
    std::vector<int> idx((size_t)n * k);
    std::vector<double> cst((size_t)n * k);
    std::vector<double> dist2(n);
    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        double sx = src[2 * i], sy = src[2 * i + 1];
        for (int j = 0; j < n; ++j) {
            double dx = sx - tgt[2 * j];
            double dy = sy - tgt[2 * j + 1];
            dist2[j] = dx * dx + dy * dy;
        }
        std::iota(order.begin(), order.end(), 0);
        std::nth_element(order.begin(), order.begin() + (k - 1), order.end(),
                         [&](int a, int b) { return dist2[a] < dist2[b]; });
        // sort the k for slightly better locality
        std::sort(order.begin(), order.begin() + k, [&](int a, int b) { return dist2[a] < dist2[b]; });
        for (int s = 0; s < k; ++s) {
            int j = order[s];
            idx[(size_t)i * k + s] = j;
            cst[(size_t)i * k + s] = std::sqrt(dist2[j]);
        }
    }

    std::vector<double> pot(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1), slot_of_match(n, -1);
    std::vector<double> dist(n);
    std::vector<int> parent_row(n);
    std::vector<int> seen_stamp(n, 0);
    int stamp = 0;
    std::vector<int> touched;
    touched.reserve(n);

    for (int source = 0; source < n; ++source) {
        ++stamp;
        if (stamp == 0) { // overflow, reset
            std::fill(seen_stamp.begin(), seen_stamp.end(), 0);
            stamp = 1;
        }
        touched.clear();
        std::priority_queue<Node> pq;

        const int* ci = idx.data() + (size_t)source * k;
        const double* cc = cst.data() + (size_t)source * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            double d = cc[s] - pot[j];
            dist[j] = d;
            parent_row[j] = source;
            seen_stamp[j] = stamp;
            touched.push_back(j);
            pq.push({d, j});
        }

        int sink = -1;
        double sink_d = 0.0;
        std::vector<char> used(n, 0);
        bool fail = false;
        while (true) {
            if (pq.empty()) { fail = true; break; }
            Node cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (used[jmin]) continue;
            if (cur.d > dist[jmin] + 1e-15) continue;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; sink_d = dist[jmin]; break; }

            int sm = slot_of_match[i];
            double cmatch = cst[(size_t)i * k + sm];
            double ui = cmatch - pot[jmin] - dist[jmin];
            const int* ci2 = idx.data() + (size_t)i * k;
            const double* cc2 = cst.data() + (size_t)i * k;
            for (int s = 0; s < k; ++s) {
                int j = ci2[s];
                if (used[j]) continue;
                double nd = cc2[s] - ui - pot[j];
                if (seen_stamp[j] != stamp || nd < dist[j]) {
                    dist[j] = nd;
                    parent_row[j] = i;
                    seen_stamp[j] = stamp;
                    if (seen_stamp[j] == stamp) touched.push_back(j);
                    pq.push({nd, j});
                }
            }
        }
        if (fail) return -1;

        for (int j : touched) if (used[j]) pot[j] += dist[j] - sink_d;

        int j = sink;
        while (true) {
            int i = parent_row[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            const int* ci3 = idx.data() + (size_t)i * k;
            int slot = -1;
            for (int s = 0; s < k; ++s) if (ci3[s] == j) { slot = s; break; }
            slot_of_match[i] = slot;
            if (i == source) break;
            j = prev;
        }
    }

    for (int i = 0; i < n; ++i) {
        rowsol[i] = col_of_row[i];
        int s = slot_of_match[i];
        col_cost_out[i] = cst[(size_t)i * k + s];
    }
    return 0;
}
