            kcost[(size_t)i * k + s] = std::sqrt(dist2[j]);
        }
    }

    std::vector<double> pot(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1), slot(n, -1);
    std::vector<double> dist(n);
    std::vector<int> parent(n);
    std::vector<char> used(n);

    for (int source = 0; source < n; ++source) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(parent.begin(), parent.end(), -1);
        std::fill(used.begin(), used.end(), 0);

        const int* ci = knn.data() + (size_t)source * k;
        const double* cc = kcost.data() + (size_t)source * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            double d = cc[s] - pot[j];
            if (d < dist[j]) {
                dist[j] = d;
                parent[j] = source;
            }
        }

        int sink = -1;
        while (true) {
            int jmin = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) if (!used[j] && dist[j] < best) {
                best = dist[j];
                jmin = j;
            }
            if (jmin < 0 || best >= INF / 2) return -1;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; break; }

            int sm = slot[i];
            double cmatch = kcost[(size_t)i * k + sm];
            double ui = cmatch - pot[jmin] - dist[jmin];
            const int* ci2 = knn.data() + (size_t)i * k;
            const double* cc2 = kcost.data() + (size_t)i * k;
            for (int s = 0; s < k; ++s) {
                int j = ci2[s];
                if (used[j]) continue;
                double nd = cc2[s] - ui - pot[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    parent[j] = i;
                }
            }
        }

        double sink_d = dist[sink];
        for (int j = 0; j < n; ++j) if (used[j]) pot[j] += dist[j] - sink_d;

        int j = sink;
        while (true) {
            int i = parent[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            const int* ci3 = knn.data() + (size_t)i * k;
            int sl = -1;
            for (int s = 0; s < k; ++s) if (ci3[s] == j) { sl = s; break; }
            if (sl < 0) return -2;
            slot[i] = sl;
            if (i == source) break;
            j = prev;
        }
    }

    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
