#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <numeric>
#include <queue>
#include <cstring>

struct QNode {
    double d;
    int j;
    bool operator<(const QNode& o) const { return d > o.d; }
};

extern "C" int geo_lap(int n, int k,
                       const double* src, const double* tgt,
                       int* rowsol) {
    const double INF = 1e100;
    std::vector<int> knn((size_t)n * k);
    std::vector<double> kcost((size_t)n * k);
    std::vector<double> dist2(n);
