        const double* cc = kcost.data() + (size_t)source * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            double d = cc[s] - pot[j];
            if (stamp[j] != cur_stamp || d < dist[j]) {
                dist[j] = d;
                parent[j] = source;
                stamp[j] = cur_stamp;
                pq.push({d, j});
            }
        }

        int sink = -1;
        while (true) {
            if (pq.empty()) return -1;
            QNode cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (used[jmin] || stamp[jmin] != cur_stamp) continue;
            if (cur.d > dist[jmin] + 1e-12) continue;
            used[jmin] = 1;
            int i = row_of_col[jmin];
