            int sm = slot[i];
            double cmatch = kcost[(size_t)i * k + sm];
            double ui = cmatch - pot[jmin] - dist[jmin];
            const int* ci2 = knn.data() + (size_t)i * k;
            const double* cc2 = kcost.data() + (size_t)i * k;
            for (int s = 0; s < k; ++s) {
                int j = ci2[s];
                if (used[j]) continue;
                double nd = cc2[s] - ui - pot[j];
                if (stamp[j] != cur_stamp || nd < dist[j]) {
                    dist[j] = nd;
                    parent[j] = i;
                    stamp[j] = cur_stamp;
