// Euclidean assignment via grid-hash kNN + successive shortest paths.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <queue>
#include <cstring>
#include <numeric>

struct QNode {
    double d;
    int j;
    bool operator<(const QNode& o) const { return d > o.d; }
};

extern "C" int grid_lap(int n, int k, int grid,
                        const double* src, const double* tgt,
                        int* rowsol) {
    const double INF = 1e100;
    // buckets
    std::vector<std::vector<int>> buckets(grid * grid);
    auto cell = [&](double x) {
        int c = (int)(x * grid);
        if (c < 0) c = 0;
        if (c >= grid) c = grid - 1;
        return c;
    };
    for (int j = 0; j < n; ++j) {
        int ix = cell(tgt[2 * j]), iy = cell(tgt[2 * j + 1]);
        buckets[ix * grid + iy].push_back(j);
    }

    std::vector<int> knn((size_t)n * k);
    std::vector<double> kcost((size_t)n * k);
    std::vector<int> cand;
    std::vector<double> cd;
    cand.reserve(n);
    cd.reserve(n);

    for (int i = 0; i < n; ++i) {
        double sx = src[2 * i], sy = src[2 * i + 1];
        int ix = cell(sx), iy = cell(sy);
        cand.clear();
        int rad = 0;
        while ((int)cand.size() < k && rad <= grid) {
            int x0 = std::max(0, ix - rad), x1 = std::min(grid - 1, ix + rad);
            int y0 = std::max(0, iy - rad), y1 = std::min(grid - 1, iy + rad);
            if (rad == 0) {
                const auto& b = buckets[ix * grid + iy];
                cand.insert(cand.end(), b.begin(), b.end());
            } else {
                for (int x = x0; x <= x1; ++x) {
                    // top and bottom rows
                    for (int y : {y0, y1}) {
                        if (y < y0 || y > y1) continue;
                        const auto& b = buckets[x * grid + y];
                        cand.insert(cand.end(), b.begin(), b.end());
                    }
                    // side columns, excluding corners already added
                    for (int y = y0 + 1; y <= y1 - 1; ++y) {
                        if (x == x0 || x == x1) {
                            const auto& b = buckets[x * grid + y];
                            cand.insert(cand.end(), b.begin(), b.end());
                        }
                    }
                }
            }
            ++rad;
        }
        // unique? targets appear once. compute distances
        cd.resize(cand.size());
        for (size_t t = 0; t < cand.size(); ++t) {
            int j = cand[t];
            double dx = sx - tgt[2 * j];
            double dy = sy - tgt[2 * j + 1];
            cd[t] = dx * dx + dy * dy;
        }
        int m = (int)cand.size();
        int kk = std::min(k, m);
        std::vector<int> ord(m);
        std::iota(ord.begin(), ord.end(), 0);
        if (kk < m) {
            std::nth_element(ord.begin(), ord.begin() + (kk - 1), ord.end(),
                             [&](int a, int b) { return cd[a] < cd[b]; });
        }
        // if fewer than k, pad by scanning all (rare)
        if (kk < k) {
            // fall back: all targets
            cand.resize(n);
            std::iota(cand.begin(), cand.end(), 0);
            cd.resize(n);
            for (int j = 0; j < n; ++j) {
                double dx = sx - tgt[2 * j];
                double dy = sy - tgt[2 * j + 1];
                cd[j] = dx * dx + dy * dy;
            }
            ord.resize(n);
            std::iota(ord.begin(), ord.end(), 0);
            std::nth_element(ord.begin(), ord.begin() + (k - 1), ord.end(),
                             [&](int a, int b) { return cd[a] < cd[b]; });
            kk = k;
            m = n;
        }
        for (int s = 0; s < k; ++s) {
            int t = ord[s];
            int j = cand[t];
            knn[(size_t)i * k + s] = j;
            kcost[(size_t)i * k + s] = std::sqrt(cd[t]);
        }
    }

    // assignment (same as knn_lap)
    std::vector<double> pot(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1), slot(n, -1);
    std::vector<double> dist(n);
    std::vector<int> parent(n);
    std::vector<int> stamp(n, 0);
    std::vector<char> used(n, 0);
    int cur_stamp = 0;

    for (int source = 0; source < n; ++source) {
        ++cur_stamp;
        std::fill(used.begin(), used.end(), 0);
        std::priority_queue<QNode> pq;
        const int* ci = knn.data() + (size_t)source * k;
        const double* cc = kcost.data() + (size_t)source * k;
        for (int s = 0; s < k; ++s) {
            int j = ci[s];
            double d = cc[s] - pot[j];
            if (stamp[j] != cur_stamp || d < dist[j]) {
                dist[j] = d;
                parent[j] = source;
                stamp[j] = cur_stamp;
                pq.push({d, j});
