        while (true) {
            int i = parent[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            const int* ci3 = knn.data() + (size_t)i * k;
            int sl = -1;
            for (int s = 0; s < k; ++s) if (ci3[s] == j) { sl = s; break; }
