// Build candidates with a grid, radius = mult * distance of k0-th neighbor (approx via expanding cells),
// then exact k0-th among a generous set, then keep everyone within mult * that.
extern "C" int full_lap(int n, int k0, double mult, int grid,
                        const double* src, const double* tgt, int* rowsol) {
    std::vector<std::vector<int>> buckets(grid * grid);
    auto cell = [&](double x) {
        int c = (int)(x * grid);
        if (c < 0) c = 0;
        if (c >= grid) c = grid - 1;
        return c;
    };
    for (int j = 0; j < n; ++j) buckets[cell(tgt[2*j]) * grid + cell(tgt[2*j+1])].push_back(j);

    std::vector<int> row_ptr(n + 1, 0);
    std::vector<int> cols;
    std::vector<double> costs;
    cols.reserve((size_t)n * 120);
    costs.reserve((size_t)n * 120);

    std::vector<int> cand;
    std::vector<double> cd;
    cand.reserve(512);
    cd.reserve(512);

    for (int i = 0; i < n; ++i) {
        double sx = src[2*i], sy = src[2*i+1];
        int ix = cell(sx), iy = cell(sy);
        cand.clear();
        int rad = 0;
        // expand until we have a comfortable superset (at least 4*k0 or whole grid)
        int need = k0 * 4;
        while ((int)cand.size() < need && rad <= grid) {
            int x0 = std::max(0, ix - rad), x1 = std::min(grid - 1, ix + rad);
            int y0 = std::max(0, iy - rad), y1 = std::min(grid - 1, iy + rad);
            for (int x = x0; x <= x1; ++x) {
                for (int y = y0; y <= y1; ++y) {
                    if (rad > 0 && x > x0 && x < x1 && y > y0 && y < y1) continue; // interior already taken
                    const auto& b = buckets[x * grid + y];
                    cand.insert(cand.end(), b.begin(), b.end());
                }
            }
            ++rad;
        }
        int m = (int)cand.size();
        cd.resize(m);
        for (int t = 0; t < m; ++t) {
            int j = cand[t];
            double dx = sx - tgt[2*j], dy = sy - tgt[2*j+1];
            cd[t] = std::sqrt(dx*dx + dy*dy);
        }
        // k0-th distance
        std::vector<double> tmp(cd);
        int kk = std::min(k0, m);
        std::nth_element(tmp.begin(), tmp.begin() + (kk - 1), tmp.end());
        double thr = tmp[kk - 1] * mult;
        // if candidate set might be truncated (didn't cover thr), expand more
        // conservative: if max radius not exhausted and farthest cand could be inside thr*something, expand until
        // the cell ring is surely outside thr.
        double cellsize = 1.0 / grid;
        while (rad <= grid) {
            double ring_inner = (rad - 1) * cellsize; // rough
            if (ring_inner > thr + cellsize * 1.5) break;
            int x0 = std::max(0, ix - rad), x1 = std::min(grid - 1, ix + rad);
            int y0 = std::max(0, iy - rad), y1 = std::min(grid - 1, iy + rad);
            size_t before = cand.size();
            for (int x = x0; x <= x1; ++x) for (int y = y0; y <= y1; ++y) {
                if (x > x0 && x < x1 && y > y0 && y < y1) continue;
                const auto& b = buckets[x * grid + y];
                cand.insert(cand.end(), b.begin(), b.end());
            }
            for (size_t t = before; t < cand.size(); ++t) {
                int j = cand[t];
                double dx = sx - tgt[2*j], dy = sy - tgt[2*j+1];
                cd.push_back(std::sqrt(dx*dx + dy*dy));
            }
            ++rad;
            if ((int)cand.size() == n) break;
        }
        row_ptr[i] = (int)cols.size();
        for (size_t t = 0; t < cand.size(); ++t) {
            if (cd[t] <= thr + 1e-12) {
                cols.push_back(cand[t]);
                costs.push_back(cd[t]);
            }
        }
        // safety: if somehow fewer than k0, keep k0 nearest
        if ((int)cols.size() - row_ptr[i] < k0) {
            cols.resize(row_ptr[i]);
            costs.resize(row_ptr[i]);
            std::vector<int> ord(cand.size());
            std::iota(ord.begin(), ord.end(), 0);
            int take = std::min(k0, (int)cand.size());
            std::nth_element(ord.begin(), ord.begin() + (take - 1), ord.end(),
                             [&](int a, int b) { return cd[a] < cd[b]; });
            for (int s = 0; s < take; ++s) {
                cols.push_back(cand[ord[s]]);
                costs.push_back(cd[ord[s]]);
            }
        }
    }
    row_ptr[n] = (int)cols.size();
    return var_lap(n, row_ptr, cols, costs, rowsol);
}
