// Assignment on a prebuilt CSR graph using Dial's algorithm (bucket Dijkstra)
// on scaled integer reduced costs. Costs are passed as doubles and scaled.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" int dial_lap(int n, const int* row_ptr, const int* cols, const double* costs,
                        int* rowsol, double scale) {
    // scale costs to int
    int nnz = row_ptr[n];
    std::vector<int> icost(nnz);
    for (int e = 0; e < nnz; ++e) {
        icost[e] = (int)std::llround(costs[e] * scale);
    }
    std::vector<long long> pot(n, 0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1), match_slot(n, -1);
    std::vector<int> match_cost(n, 0);

    // buckets: reduced costs are nonnegative after potential init? not initially.
    // We'll shift per search by the minimum label.
    // Use a map-like vector of deques indexed by reduced distance, grown as needed.
    // For speed, use a circular buffer of fixed range. Max reduced cost per edge:
    int maxc = 0;
    for (int c : icost) if (c > maxc) maxc = c;
    // A path reduced cost is at most n*maxc but with potentials typically small.
    // Use SPFA? Let's stick with a simple radix: vector of vectors, indexed by dist, with a moving start.
    // Cap: if a label exceeds BUCKETS, fall back to scan. We'll size generously.
    const int BUCKETS = std::max(1024, maxc * 4 + 8);
    std::vector<std::vector<int>> buckets(BUCKETS);
    for (auto& b : buckets) b.reserve(8);
    std::vector<int> dist(n), parent(n);
    std::vector<int> stamp(n, 0);
    std::vector<char> used(n, 0);
    int cur_stamp = 0;
    const int INF = 0x3fffffff;

    for (int source = 0; source < n; ++source) {
        ++cur_stamp;
        std::fill(used.begin(), used.end(), 0);
        for (auto& b : buckets) b.clear();

        auto relax_new = [&](int j, int d, int par) {
            if (stamp[j] != cur_stamp || d < dist[j]) {
                dist[j] = d;
                parent[j] = par;
                stamp[j] = cur_stamp;
                if (d >= BUCKETS) return false;
                buckets[d].push_back(j);
                return true;
            }
            return true;
        };

        bool overflow = false;
        for (int e = row_ptr[source]; e < row_ptr[source + 1]; ++e) {
            int j = cols[e];
            long long d = (long long)icost[e] - pot[j];
            if (d < 0) d = 0; // numerical
            if (!relax_new(j, (int)d, source)) overflow = true;
        }
        if (overflow) return -3;

        int sink = -1;
        int sink_d = 0;
        int cursor = 0;
        // find first nonempty
        while (cursor < BUCKETS && buckets[cursor].empty()) ++cursor;
        while (true) {
            if (cursor >= BUCKETS) return -4;
            while (cursor < BUCKETS && buckets[cursor].empty()) ++cursor;
            if (cursor >= BUCKETS) return -4;
            int jmin = buckets[cursor].back();
            buckets[cursor].pop_back();
            if (stamp[jmin] != cur_stamp || used[jmin] || dist[jmin] != cursor) continue;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; sink_d = cursor; break; }
            long long ui = (long long)match_cost[i] - pot[jmin] - dist[jmin];
            for (int e = row_ptr[i]; e < row_ptr[i + 1]; ++e) {
                int j = cols[e];
                if (used[j]) continue;
                long long nd = (long long)icost[e] - ui - pot[j];
                if (nd < 0) nd = 0;
                if (stamp[j] != cur_stamp || nd < dist[j]) {
                    if (nd >= BUCKETS) return -3;
                    dist[j] = (int)nd;
                    parent[j] = i;
                    stamp[j] = cur_stamp;
                    buckets[(int)nd].push_back(j);
                    if ((int)nd < cursor) cursor = (int)nd;
                }
            }
        }

        for (int j = 0; j < n; ++j) if (used[j]) pot[j] += (long long)dist[j] - sink_d;

        int j = sink;
        while (true) {
            int i = parent[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            int mc = 0; bool found = false; int sl = -1;
            for (int e = row_ptr[i]; e < row_ptr[i + 1]; ++e) if (cols[e] == j) { mc = icost[e]; found = true; sl = e; break; }
            if (!found) return -2;
            match_cost[i] = mc;
            match_slot[i] = sl;
            if (i == source) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
