#include <vector>
#include <cstdint>
#include <algorithm>
#include <queue>
#include <cstring>

struct QNode { double d; int j; bool operator<(const QNode& o) const { return d > o.d; } };

extern "C" int fast_lap(int n, const int* row_ptr, const int* cols, const double* costs, int* rowsol) {
    std::vector<double> pot(n, 0.0), dist(n), match_cost(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1), parent(n), stamp(n, 0), match_edge(n, -1);
    std::vector<char> used(n, 0);
    int cur_stamp = 0;
    std::vector<int> touched;
    touched.reserve(n);

    for (int source = 0; source < n; ++source) {
        ++cur_stamp;
        touched.clear();
        std::priority_queue<QNode> pq;
        for (int e = row_ptr[source]; e < row_ptr[source + 1]; ++e) {
            int j = cols[e];
            double d = costs[e] - pot[j];
            if (stamp[j] != cur_stamp || d < dist[j]) {
                if (stamp[j] != cur_stamp) touched.push_back(j);
                dist[j] = d; parent[j] = source; stamp[j] = cur_stamp;
                pq.push({d, j});
            }
        }
        int sink = -1;
        while (true) {
            if (pq.empty()) return -1;
            QNode cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (stamp[jmin] != cur_stamp || used[jmin]) continue;
            if (cur.d > dist[jmin] + 1e-12) continue;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; break; }
            double ui = match_cost[i] - pot[jmin] - dist[jmin];
            int me = match_edge[i];
            for (int e = row_ptr[i]; e < row_ptr[i + 1]; ++e) {
                if (e == me) continue;
                int j = cols[e];
                if (used[j]) continue;
                double nd = costs[e] - ui - pot[j];
                if (stamp[j] != cur_stamp || nd < dist[j]) {
                    if (stamp[j] != cur_stamp) touched.push_back(j);
                    dist[j] = nd; parent[j] = i; stamp[j] = cur_stamp;
                    pq.push({nd, j});
                }
            }
        }
        double sink_d = dist[sink];
        for (int j : touched) if (used[j]) pot[j] += dist[j] - sink_d;
        // clear used flags only on touched
        for (int j : touched) used[j] = 0;

        int j = sink;
        while (true) {
            int i = parent[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            int found = -1;
            for (int e = row_ptr[i]; e < row_ptr[i + 1]; ++e) if (cols[e] == j) { found = e; break; }
            if (found < 0) return -2;
            match_edge[i] = found;
            match_cost[i] = costs[found];
            if (i == source) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
