// Network simplex for the transportation problem, following the structure of
// LEMON's NetworkSimplex (public-domain algorithm description; this is an
// independent implementation of the classical algorithm).
//
// Dense cost matrix, supplies a[i], demands b[j], all positive, sum equal.
// Returns the basic optimal flow as a dense matrix.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

extern "C" int network_simplex(int n, int m, const double* a, const double* b,
                               const double* cost, double* flow_out) {
    // Nodes: sources 0..n-1, sinks n..n+m-1, root n+m
    const int S = n, T = m;
    const int N = S + T + 1;          // including root
    const int ROOT = S + T;
    const int ARC = S * T;            // real arcs, then artificial
    const int ART = S + T;            // artificial arcs to root
    const int MAXA = ARC + ART;

    const double INF = 1e100;
    const int NO = -1;

    // Arc data for real arcs stored as i*T+j. Artificial: ARC+i for source i (to root),
    // ARC+S+j for sink j (from root).
    auto arc_src = [&](int aidx) {
        if (aidx < ARC) return aidx / T;
        if (aidx < ARC + S) return aidx - ARC;
        return ROOT;
    };
    auto arc_tgt = [&](int aidx) {
        if (aidx < ARC) return S + (aidx % T);
        if (aidx < ARC + S) return ROOT;
        return S + (aidx - ARC - S);
    };
    auto arc_cost = [&](int aidx) -> double {
        if (aidx < ARC) return cost[aidx];
        return 0.0; // artificial, feasible since supplies equal demands; cost 0 is fine? 
        // Using 0 is OK only if we start feasible. We will build a feasible spanning tree
        // with a greedy/northwest start, so artificial arcs carry 0 and have cost 0.
    };

    // Tree representation (LEMON-style)
    std::vector<int> parent(N, NO);      // parent node
    std::vector<int> parent_arc(N, NO);  // arc connecting node to parent
    std::vector<int> pred_dir(N, 0);     // +1 if parent arc is toward parent (node is source of arc? )
    // We'll store: for each non-root node, the tree arc and whether flow goes to parent.
    std::vector<int> thread(N);          // depth-first thread
    std::vector<int> rev_thread(N);
    std::vector<int> succ_num(N);
    std::vector<int> last_succ(N);
    std::vector<int> depth(N);
    std::vector<double> potential(N, 0.0);
    std::vector<double> flow(MAXA, 0.0);
    std::vector<char> state(MAXA, 0);    // 0 lower (flow 0), 1 tree, 2 upper (not used, uncapacitated)

    // Build an initial feasible tree: northwest corner rule + root connections for unused.
    // First, compute a basic feasible solution via northwest corner.
    std::vector<double> as(a, a + S), bs(b, b + T);
    std::vector<int> basic;
    basic.reserve(S + T - 1);
    int i = 0, j = 0;
    while (i < S && j < T) {
        int aidx = i * T + j;
        double f = std::min(as[i], bs[j]);
        flow[aidx] = f;
        basic.push_back(aidx);
        state[aidx] = 1;
        as[i] -= f;
        bs[j] -= f;
        if (as[i] <= 1e-15 && bs[j] <= 1e-15) {
            // degenerate step: advance both, but need an extra basic zero arc if not last
            if (i + 1 < S && j + 1 < T) {
                // add zero arc (i, j+1) to keep basis size, leave i's remaining 0
                // actually both exhausted; add (i, j+1) with 0 flow and don't consume
                int z = i * T + (j + 1);
                if (state[z] == 0) { state[z] = 1; basic.push_back(z); }
            }
            ++i; ++j;
        } else if (as[i] <= 1e-15) {
            ++i;
        } else {
            ++j;
        }
    }
    // Connect every node not yet in the forest to root with artificial arcs.
    // First build forest from basic arcs via union-find, then link components to root.
    std::vector<int> uf(N);
    std::iota(uf.begin(), uf.end(), 0);
    std::function<int(int)> find = [&](int x) { return uf[x] == x ? x : uf[x] = find(uf[x]); };
    auto unite = [&](int a, int b) {
        a = find(a); b = find(b);
        if (a != b) uf[a] = b;
    };
    for (int aidx : basic) unite(arc_src(aidx), arc_tgt(aidx));

    // artificial arcs
    for (int s = 0; s < S; ++s) {
        if (find(s) != find(ROOT)) {
            int aidx = ARC + s;
            state[aidx] = 1;
            flow[aidx] = 0;
            basic.push_back(aidx);
            unite(s, ROOT);
        }
    }
    for (int t = 0; t < T; ++t) {
        if (find(S + t) != find(ROOT)) {
            int aidx = ARC + S + t;
            state[aidx] = 1;
            flow[aidx] = 0;
            basic.push_back(aidx);
            unite(S + t, ROOT);
        }
    }

    // Now basic should have N-1 arcs forming a spanning tree. Build parent pointers by BFS/DFS from root.
    std::vector<std::vector<std::pair<int,int>>> adj(N); // node -> (neighbor, arc)
    for (int aidx : basic) {
        int u = arc_src(aidx), v = arc_tgt(aidx);
        adj[u].push_back({v, aidx});
        adj[v].push_back({u, aidx});
    }
    std::vector<char> vis(N, 0);
    std::vector<int> order;
    order.reserve(N);
    // iterative DFS to set parent and also build thread (preorder)
    std::vector<int> stack = {ROOT};
    parent[ROOT] = NO;
    parent_arc[ROOT] = NO;
    depth[ROOT] = 0;
    vis[ROOT] = 1;
    potential[ROOT] = 0;
    while (!stack.empty()) {
        int u = stack.back(); stack.pop_back();
        order.push_back(u);
        for (auto [v, aidx] : adj[u]) if (!vis[v]) {
            vis[v] = 1;
            parent[v] = u;
            parent_arc[v] = aidx;
            depth[v] = depth[u] + 1;
            // potential: cost(u->v) = pi[u] - pi[v] for reduced cost c - pi_src + pi_tgt = 0 on tree arcs
            // For arc src->tgt: c_pi = c - pi[src] + pi[tgt] = 0 => pi[tgt] = pi[src] - c
            int s = arc_src(aidx), t = arc_tgt(aidx);
            double c = arc_cost(aidx);
            if (v == t && u == s) {
                potential[v] = potential[u] - c;
            } else if (v == s && u == t) {
                potential[v] = potential[u] + c;
            }
            stack.push_back(v);
        }
    }
    // thread = preorder via a proper DFS (stack above is not preorder-sibling ordered). Rebuild with recursion-like.
    // Use explicit DFS for thread.
    std::fill(vis.begin(), vis.end(), 0);
    std::vector<int> pre;
    std::vector<int> st = {ROOT};
    // build children lists
    std::vector<std::vector<int>> children(N);
    for (int v = 0; v < N; ++v) if (v != ROOT && parent[v] != NO) children[parent[v]].push_back(v);
    std::function<void(int)> dfs = [&](int u) {
        pre.push_back(u);
        for (int v : children[u]) dfs(v);
    };
    dfs(ROOT);
    for (int k = 0; k < N; ++k) {
        thread[pre[k]] = pre[(k + 1) % N];
        rev_thread[pre[(k + 1) % N]] = pre[k];
    }
    // succ_num and last_succ
    for (int k = N - 1; k >= 0; --k) {
        int u = pre[k];
        int last = u;
        int num = 1;
        for (int v : children[u]) {
            num += succ_num[v];
            last = last_succ[v];
        }
        succ_num[u] = num;
        last_succ[u] = last;
    }

    auto reduced = [&](int aidx) -> double {
        return arc_cost(aidx) - potential[arc_src(aidx)] + potential[arc_tgt(aidx)];
    };

    // Pivot loop
    const int MAX_ITER = 1000000;
    int iter = 0;
    std::vector<int> candidates;
    candidates.reserve(ARC);
    for (int aidx = 0; aidx < ARC; ++aidx) if (state[aidx] != 1) candidates.push_back(aidx);

    while (iter++ < MAX_ITER) {
        // find entering arc: most negative reduced cost (Dantzig), block search for speed
        int enter = NO;
        double best = -1e-12;
        // partial pricing: scan a window
        static int start = 0;
        int scanned = 0;
        int idx = start;
        int limit = std::min((int)candidates.size(), std::max(256, (int)candidates.size() / 20));
        while (scanned < (int)candidates.size()) {
            int aidx = candidates[idx];
            if (state[aidx] != 1) {
                double r = reduced(aidx);
                if (r < best) { best = r; enter = aidx; }
            }
            ++scanned;
            idx++; if (idx == (int)candidates.size()) idx = 0;
            if (enter != NO && scanned >= limit) break;
        }
        start = idx;
        if (enter == NO) break; // optimal

        // entering arc u->v. Find cycle: join u and v up to LCA, leaving arc is min residual on the reverse orientation.
        int u = arc_src(enter), v = arc_tgt(enter);
        // augmenting direction: flow increases on enter, so we look for the leaving arc among reverse-direction tree arcs.
        // Walk both up to same depth then together.
        int uu = u, vv = v;
        double delta = INF;
        int leave = NO;
        int leave_node = NO; // the node whose parent arc leaves, on the side that saturates
        // Collect path nodes from u to LCA (these arcs go "up" and flow on them decreases if oriented toward LCA? )
        // Simpler: mark the stem.
        // We'll compute join.
        int x = u, y = v;
        while (depth[x] > depth[y]) x = parent[x];
        while (depth[y] > depth[x]) y = parent[y];
        while (x != y) { x = parent[x]; y = parent[y]; }
        int lca = x;

        // Side of u (source of entering arc): flow on path u->lca must decrease on arcs oriented u-ward? 
        // Entering arc pushes flow from u to v. So along u up to lca, we need flow coming into the path, i.e.
        // tree arcs oriented from parent toward the node (down the tree, away from lca) have their flow decreased,
        // arcs oriented from node to parent have flow increased (uncapacitated, never leave).
        // Since all real arcs are uncapacitated upward, the leaving arc is a downward arc (parent -> node) on the u side,
        // or an upward arc (node -> parent) on the v side, with smallest flow.
        // Artificial arcs are also uncapacitated in our model (flow can be negative?!). 
        // PROBLEM: artificial arcs with cost 0 and unbounded both ways make this not a proper formulation.
        // We only use them to connect the basis; their flow must stay 0 if the real solution is feasible.
        // Treat artificial flow as free (can go negative) so they never block. They should end at 0.
        auto is_art = [&](int aidx) { return aidx >= ARC; };

        // u side
        for (int node = u; node != lca; node = parent[node]) {
            int aidx = parent_arc[node];
            int s = arc_src(aidx), t = arc_tgt(aidx);
            // downward orientation means parent is source and node is target: flow decreases
            if (!is_art(aidx) && parent[node] == s && node == t) {
                if (flow[aidx] < delta) { delta = flow[aidx]; leave = aidx; leave_node = node; }
            }
        }
        // v side: upward orientation (node is source, parent is target) flow decreases
        int vside_leave_node = NO;
        for (int node = v; node != lca; node = parent[node]) {
            int aidx = parent_arc[node];
            int s = arc_src(aidx), t = arc_tgt(aidx);
            if (!is_art(aidx) && node == s && parent[node] == t) {
                if (flow[aidx] < delta) { delta = flow[aidx]; leave = aidx; leave_node = node; }
            }
        }
        if (leave == NO) {
            // unbounded? shouldn't happen for balanced transportation with a complete bipartite graph
            // force a degenerate pivot: leave = parent arc of u if u!=lca else v
            if (u != lca) { leave_node = u; leave = parent_arc[u]; delta = 0; }
            else if (v != lca) { leave_node = v; leave = parent_arc[v]; delta = 0; }
            else return -5;
        }
        if (delta == INF) delta = 0;

        // augment
        flow[enter] += delta;
        for (int node = u; node != lca; node = parent[node]) {
            int aidx = parent_arc[node];
            int s = arc_src(aidx);
            if (parent[node] == s) flow[aidx] -= delta; else flow[aidx] += delta;
        }
        for (int node = v; node != lca; node = parent[node]) {
            int aidx = parent_arc[node];
            int s = arc_src(aidx);
            if (node == s) flow[aidx] -= delta; else flow[aidx] += delta;
        }

        // pivot tree if leave != enter
        if (leave != enter) {
            state[leave] = 0;
            flow[leave] = 0;
            state[enter] = 1;
            // Update tree structure. This is the delicate part.
            // The leaving arc's child-side subtree is reattached under the entering arc.
            // Determine which endpoint of leave is in the subtree that contains the entering attachment.
            // Standard: the subtree rooted at leave_node is detached and the entering arc becomes its new link.
            // But only if leave_node is on the cycle. We set leave_node above.
            // REATTACHMENT: nodes in subtree of leave_node change parent chain.
            // Find which of enter's endpoints is in the subtree.
            int sub = leave_node;
            // entering arc connects u and v; one of them is in subtree of sub (or is sub).
            auto in_subtree = [&](int node, int root) {
                // node is successor of root in thread order within succ_num
                // Use depth walk (n small enough in tests)
                while (node != NO && node != root && node != ROOT) node = parent[node];
                return node == root;
            };
            int in_sub = in_subtree(u, sub) ? u : v;
            int out_sub = (in_sub == u) ? v : u;
            // The new parent of `sub`'s chain: we reverse the path from in_sub up to sub, and attach in_sub's side to out_sub via enter.
            // Implement by reversing parent links along in_sub -> ... -> sub, then parent[in_sub] = out_sub, parent_arc = enter.
            // Collect path from in_sub up to sub (inclusive)
            std::vector<int> path;
            for (int node = in_sub; ; node = parent[node]) {
                path.push_back(node);
                if (node == sub) break;
            }
            // reverse links
            for (int k = (int)path.size() - 1; k >= 1; --k) {
                int node = path[k];
                int child = path[k - 1];
                parent[node] = child;
                parent_arc[node] = parent_arc[child];
            }
            parent[in_sub] = out_sub;
            parent_arc[in_sub] = enter;

            // rebuild depth, potential, thread, children-derived indices for the affected region.
            // For correctness first, rebuild the whole tree indexing (O(N)).
            children.assign(N, {});
            for (int node = 0; node < N; ++node) if (node != ROOT) children[parent[node]].push_back(node);
            // potentials: BFS/DFS from root
            std::function<void(int)> rec = [&](int node) {
                for (int ch : children[node]) {
                    depth[ch] = depth[node] + 1;
                    int aidx = parent_arc[ch];
                    int s = arc_src(aidx), t = arc_tgt(aidx);
                    double c = arc_cost(aidx);
                    if (ch == t && node == s) potential[ch] = potential[node] - c;
                    else potential[ch] = potential[node] + c;
                    rec(ch);
                }
            };
            depth[ROOT] = 0;
            potential[ROOT] = 0;
            rec(ROOT);
            pre.clear();
            std::function<void(int)> dfs2 = [&](int node) {
                pre.push_back(node);
                for (int ch : children[node]) dfs2(ch);
            };
            dfs2(ROOT);
            for (int k = 0; k < N; ++k) {
                thread[pre[k]] = pre[(k + 1) % N];
                rev_thread[pre[(k + 1) % N]] = pre[k];
            }
            for (int k = N - 1; k >= 0; --k) {
                int node = pre[k];
                int last = node, num = 1;
                for (int ch : children[node]) { num += succ_num[ch]; last = last_succ[ch]; }
                succ_num[node] = num;
                last_succ[node] = last;
            }
        } else {
            // enter was also leave (degenerate weird) 
            state[enter] = 1;
        }
    }

    if (iter >= MAX_ITER) return -6;
    std::memset(flow_out, 0, sizeof(double) * ARC);
    for (int aidx = 0; aidx < ARC; ++aidx) if (flow[aidx] != 0.0) flow_out[aidx] = flow[aidx];
    // also write tree arcs with zero? already 0
    return iter;
}

