// Exact Euclidean transportation for equal-mass uniform histograms via
// successive shortest paths. Candidate edges are generated from a spatial
// grid and expanded until the Dijkstra frontier is provably complete.
//
// For the assignment case (all weights equal), this returns the basic optimal
// plan: one target per source.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <queue>
#include <cstring>
#include <numeric>

struct QN { double d; int j; bool operator<(const QN& o) const { return d > o.d; } };

extern "C" int geo_assign(int n, const double* src, const double* tgt, int* rowsol) {
    const double INF = 1e100;
    const int G = 40;
    std::vector<std::vector<int>> buckets(G * G);
    auto cell = [&](double x) {
        int c = (int)(x * G);
        if (c < 0) c = 0;
        if (c >= G) c = G - 1;
        return c;
    };
    for (int j = 0; j < n; ++j) buckets[cell(tgt[2 * j]) * G + cell(tgt[2 * j + 1])].push_back(j);

    std::vector<double> pot(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);
    std::vector<double> match_cost(n, 0.0);
    std::vector<double> dist(n);
    std::vector<int> parent(n), stamp(n, 0);
    std::vector<char> used(n, 0);
    int cur = 0;

    // per-source expansion state reused
    std::vector<int> radius(n, -1);          // how far this row's edges have been generated, in cells
    std::vector<std::vector<int>> adj(n);    // generated target indices
    std::vector<std::vector<double>> cst(n); // generated costs
    std::vector<std::vector<char>> seen_col(n); // too heavy? n*n char = 360KB at n=600, OK
    for (int i = 0; i < n; ++i) seen_col[i].assign(n, 0);

    auto ensure = [&](int i, double need_cost) {
        // generate cells until the nearest not-yet-generated target is > need_cost
        // We expand rings until ring inner bound > need_cost.
        double sx = src[2 * i], sy = src[2 * i + 1];
        int ix = cell(sx), iy = cell(sy);
        double cellsize = 1.0 / G;
        while (true) {
            int rad = radius[i] + 1;
            // inner distance from source to this ring (0 for rad 0)
            double inner = 0;
            if (rad > 0) {
                // minimum possible distance to a point in the ring: (rad-1)*cellsize, minus nothing
                // a cell at chebyshev radius rad has points at least (rad-1)*cellsize away only if
                // source is at the far side. Conservative: (rad - 1) * cellsize is NOT always a lower
                // bound. Use (rad - 1) * cellsize only when source is inside its cell. The closest point
                // of a cell at chebyshev distance rad is at least (rad - 1) * cellsize from the source cell's
                // far corner... safest lower bound is (rad - 1) * cellsize - cellsize = (rad - 2)*cellsize.
                inner = (rad - 1) * cellsize;
                // account for source not at cell edge toward the ring: inner can be smaller by almost cellsize
                // so lower bound is max(0, (rad-1)*cellsize - cellsize) = (rad-2)*cellsize
                inner = std::max(0.0, (rad - 1) * cellsize - cellsize);
            }
            if (rad > 0 && inner > need_cost) break;
            if (rad > G + 2) break;
            int x0 = std::max(0, ix - rad), x1 = std::min(G - 1, ix + rad);
            int y0 = std::max(0, iy - rad), y1 = std::min(G - 1, iy + rad);
            if (rad == 0) {
                for (int j : buckets[ix * G + iy]) if (!seen_col[i][j]) {
                    seen_col[i][j] = 1;
                    double dx = sx - tgt[2 * j], dy = sy - tgt[2 * j + 1];
                    adj[i].push_back(j);
                    cst[i].push_back(std::sqrt(dx * dx + dy * dy));
                }
            } else {
                for (int x = x0; x <= x1; ++x) for (int y = y0; y <= y1; ++y) {
                    if (x > x0 && x < x1 && y > y0 && y < y1) continue;
                    for (int j : buckets[x * G + y]) if (!seen_col[i][j]) {
                        seen_col[i][j] = 1;
                        double dx = sx - tgt[2 * j], dy = sy - tgt[2 * j + 1];
                        adj[i].push_back(j);
                        cst[i].push_back(std::sqrt(dx * dx + dy * dy));
                    }
                }
            }
            radius[i] = rad;
            if (x0 == 0 && x1 == G - 1 && y0 == 0 && y1 == G - 1) break;
        }
    };

    for (int source = 0; source < n; ++source) {
        ++cur;
        std::fill(used.begin(), used.end(), 0);
        std::priority_queue<QN> pq;
        // initialize by expanding source until we have some edges; start with a modest radius
        ensure(source, 0.05);
        if (adj[source].empty()) ensure(source, 1e9);
        for (size_t s = 0; s < adj[source].size(); ++s) {
            int j = adj[source][s];
            double d = cst[source][s] - pot[j];
            if (stamp[j] != cur || d < dist[j]) {
                dist[j] = d; parent[j] = source; stamp[j] = cur;
                pq.push({d, j});
            }
        }
        int sink = -1;
        while (true) {
            // Before popping, make sure every matched row that could improve the frontier
            // has generated all edges cheaper than (frontier + something). This is incomplete
            // in this draft — expand all rows fully for correctness test on small n.
            if (pq.empty()) return -1;
            QN q = pq.top(); pq.pop();
            int jmin = q.j;
            if (used[jmin] || stamp[jmin] != cur) continue;
            if (q.d > dist[jmin] + 1e-12) continue;
            used[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; break; }
            // expand this row fully for now (correctness)
            ensure(i, 1e9);
            double ui = match_cost[i] - pot[jmin] - dist[jmin];
            for (size_t s = 0; s < adj[i].size(); ++s) {
                int j = adj[i][s];
                if (used[j]) continue;
                double nd = cst[i][s] - ui - pot[j];
                if (stamp[j] != cur || nd < dist[j]) {
                    dist[j] = nd; parent[j] = i; stamp[j] = cur;
                    pq.push({nd, j});
                }
            }
        }
        double sink_d = dist[sink];
        for (int j = 0; j < n; ++j) if (used[j]) pot[j] += dist[j] - sink_d;
        int j = sink;
        while (true) {
            int i = parent[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            // find cost
            double mc = 0; bool found = false;
            for (size_t s = 0; s < adj[i].size(); ++s) if (adj[i][s] == j) { mc = cst[i][s]; found = true; break; }
            if (!found) return -2;
            match_cost[i] = mc;
            if (i == source) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
    return 0;
}
