// Jonker-Volgenant dense LAP with column reduction, augmenting row reduction,
// and Dijkstra augmentation using a binary heap over a dense row scan.
// Independent implementation of the algorithm in Jonker & Volgenant, Computing 1987.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <queue>
#include <cstring>
#include <numeric>

struct QN { double key; int j; bool operator<(const QN& o) const { return key > o.key; } };

extern "C" void jv(int n, const double* cost, int* rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> col_of_row(n, -1), row_of_col(n, -1);

    // ---- column reduction ----
    // v[j] = min_i cost[i,j]; assign column to that row if free, scanning columns right to left
    std::vector<char> row_taken(n, 0);
    for (int j = n - 1; j >= 0; --j) {
        double mn = INF; int imin = 0;
        for (int i = 0; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < mn) { mn = c; imin = i; }
        }
        v[j] = mn;
        if (!row_taken[imin]) {
            row_taken[imin] = 1;
            col_of_row[imin] = j;
            row_of_col[j] = imin;
            u[imin] = 0.0; // cost - v = 0
        }
    }

    // ---- reduction transfer ----
    std::vector<int> free_rows;
    free_rows.reserve(n);
    for (int i = 0; i < n; ++i) if (!row_taken[i]) free_rows.push_back(i);

    std::vector<int> still;
    still.reserve(free_rows.size());
    for (int i : free_rows) {
        const double* crow = cost + (size_t)i * n;
        double mn = INF; int j1 = 0;
        for (int j = 0; j < n; ++j) {
            double h = crow[j] - v[j];
            if (h < mn) { mn = h; j1 = j; }
        }
        u[i] = mn;
        int i0 = row_of_col[j1];
        if (i0 < 0) {
            col_of_row[i] = j1; row_of_col[j1] = i; row_taken[i] = 1;
            continue;
        }
        // second smallest reduced cost of the assigned row i0
        const double* crow0 = cost + (size_t)i0 * n;
        double mn2 = INF;
        double u0 = crow0[j1] - v[j1];
        for (int j = 0; j < n; ++j) if (j != j1) {
            double h = crow0[j] - v[j] - u0;
            if (h < mn2) mn2 = h;
        }
        if (mn2 <= 1e-12) {
            // transfer
            col_of_row[i] = j1; row_of_col[j1] = i; row_taken[i] = 1;
            col_of_row[i0] = -1; row_taken[i0] = 0; u[i0] = 0;
            still.push_back(i0);
        } else {
            still.push_back(i);
        }
    }
    free_rows.swap(still);

    // ---- augmenting row reduction, 2 passes ----
    for (int pass = 0; pass < 2; ++pass) {
        still.clear();
        for (int i : free_rows) {
            const double* crow = cost + (size_t)i * n;
            double umin = INF, usub = INF; int jmin = 0;
            for (int j = 0; j < n; ++j) {
                double h = crow[j] - v[j];
                if (h < usub) {
                    if (h >= umin) usub = h;
                    else { usub = umin; umin = h; jmin = j; }
                }
            }
            u[i] = umin;
            int i0 = row_of_col[jmin];
            if (umin < usub - 1e-15) {
                v[jmin] -= (usub - umin);
                // reassign
                if (i0 >= 0) { col_of_row[i0] = -1; row_taken[i0] = 0; still.push_back(i0); }
                col_of_row[i] = jmin; row_of_col[jmin] = i; row_taken[i] = 1;
            } else if (i0 < 0) {
                col_of_row[i] = jmin; row_of_col[jmin] = i; row_taken[i] = 1;
            } else if (pass == 1) {
                // last pass: take it anyway
                col_of_row[i0] = -1; row_taken[i0] = 0; still.push_back(i0);
                col_of_row[i] = jmin; row_of_col[jmin] = i; row_taken[i] = 1;
            } else {
                still.push_back(i);
            }
        }
        free_rows.swap(still);
        if (free_rows.empty()) break;
    }

    // ---- augmentation ----
    std::vector<double> dist(n);
    std::vector<int> pred(n), stamp(n, 0);
    std::vector<char> scanned(n, 0);
    int cur = 0;
    std::vector<int> touched;
    touched.reserve(n);

    for (int freerow : free_rows) {
        ++cur;
        touched.clear();
        const double* crow = cost + (size_t)freerow * n;
        double best = INF; int jbest = 0;
        for (int j = 0; j < n; ++j) {
            dist[j] = crow[j] - v[j];
            pred[j] = freerow;
            if (dist[j] < best) { best = dist[j]; jbest = j; }
        }
        // Dijkstra with linear scan (dense). Column reduction should have removed most free rows,
        // so this loop runs few times. Each is O(n^2).
        std::fill(scanned.begin(), scanned.end(), 0);
        int sink = -1; double sink_d = 0;
        while (true) {
            double mn = INF; int jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < mn) { mn = dist[j]; jmin = j; }
            scanned[jmin] = 1;
            int i = row_of_col[jmin];
            if (i < 0) { sink = jmin; sink_d = mn; break; }
            const double* crowi = cost + (size_t)i * n;
            double ui = crowi[jmin] - v[jmin] - mn;
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double nd = crowi[j] - v[j] - ui;
                if (nd < dist[j]) { dist[j] = nd; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) {
            double delta = dist[j] - sink_d;
            v[j] += delta;
            int i = row_of_col[j];
            if (i >= 0) u[i] -= delta;
        }
        u[freerow] = sink_d;
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            if (i == freerow) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = col_of_row[i];
}
