// Epsilon-scaling auction for the dense assignment problem (Bertsekas).
// Maximizes -cost. Returns a perfect matching. For a sufficiently small final
// epsilon relative to the cost gap, the matching is optimal.
#include <vector>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <cstring>

extern "C" int auction(int n, const double* cost, int* rowsol, double eps_final, int* iters_out) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1);
    std::vector<int> unassigned(n);
    double cmax = 0;
    for (size_t k = 0, N = (size_t)n * n; k < N; ++k) cmax = std::max(cmax, cost[k]);
    double eps = std::max(cmax / 4.0, eps_final);
    int total_iters = 0;
    while (true) {
        std::fill(price.begin(), price.end(), 0.0);
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        const int GUARD = n * 40;
        while (nfree > 0 && guard < GUARD) {
            ++guard;
            int i = unassigned[--nfree];
            const double* crow = cost + (size_t)i * n;
            double best = -1e300, second = -1e300;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double val = -crow[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            if (second < -1e299) second = best;
            price[jbest] += (best - second) + eps;
            int prev = owner[jbest];
            owner[jbest] = i;
            assign[i] = jbest;
            if (prev >= 0) unassigned[nfree++] = prev;
        }
        total_iters += guard;
        if (nfree > 0) { if (iters_out) *iters_out = total_iters; return -1; }
        if (eps <= eps_final * 1.01) break;
        eps = std::max(eps_final, eps * 0.2);
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
    if (iters_out) *iters_out = total_iters;
    return 0;
}
